### 1.6. Capa Web: Controlador RESTful y Códigos HTTP Semánticos

El controlador expone los endpoints HTTP. Utiliza `ResponseEntity<T>` para configurar explícitamente tanto el cuerpo de la respuesta como los códigos de estado semánticos (`200 OK`, `201 Created`).

Crea el archivo `src/main/java/es/pildoras/app/controller/EmpleadoController.java`:

```java
package es.pildoras.app.controller;

import java.net.URI;
import java.util.List;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
import es.pildoras.app.dto.EmpleadoRequestDTO;
import es.pildoras.app.dto.EmpleadoResponseDTO;
import es.pildoras.app.service.EmpleadoService;
import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/empleados")
public class EmpleadoController {

    private final EmpleadoService empleadoService;

    public EmpleadoController(EmpleadoService empleadoService) {
        this.empleadoService = empleadoService;
    }

    @GetMapping
    public ResponseEntity<List<EmpleadoResponseDTO>> obtenerEmpleados() {
        return ResponseEntity.ok(empleadoService.listarTodos()); // 200 OK
    }

    @GetMapping("/{id}")
    public ResponseEntity<EmpleadoResponseDTO> obtenerPorId(@PathVariable Long id) {
        return ResponseEntity.ok(empleadoService.buscarPorId(id)); // 200 OK
    }

    @PostMapping
    public ResponseEntity<EmpleadoResponseDTO> crearEmpleado(@Valid @RequestBody EmpleadoRequestDTO peticion) {
        EmpleadoResponseDTO nuevo = empleadoService.guardar(peticion);

        // Construye dinámicamente la URI del nuevo recurso: /api/empleados/{id}
        URI ubicacion = ServletUriComponentsBuilder.fromCurrentRequest()
                .path("/{id}")
                .buildAndExpand(nuevo.getId())
                .toUri();

        // 201 Created con cabecera Location y cuerpo deserializado
        return ResponseEntity.created(ubicacion).body(nuevo);
    }
}
```

